select location, budget_bucket, department_count, finance_count from (select location, case when budget >= 3048000 then 'high' when budget >= 900000 then 'mid' else 'low' end as budget_bucket, count(*) as department_count, count(case when dept_name = 'Finance' then 1 end) as finance_count from departments group by location, case when budget >= 3048000 then 'high' when budget >= 900000 then 'mid' else 'low' end) as agg where department_count >= 8;
